Ваш сервер проверяет `hash` через HMAC-SHA-256 с токеном бота. Партнёр проверяет `signature` через Ed25519 с публичным ключом Telegram — токен ему не нужен.

Для Ed25519 установите `cryptography`: `pip install cryptography`.

```python
import base64
import binascii
import hmac
import json
import time
from urllib.parse import parse_qsl

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey


TELEGRAM_PROD_KEY = (
    "e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d"
)
TELEGRAM_TEST_KEY = (
    "40055058a4ee38156a06562e52eece92a771bcd8346a8c4615cb7376eddf72ec"
)


def _parse(init_data: str) -> dict[str, str]:
    # URL-декодирование ровно один раз. JSON пока остаётся строкой.
    try:
        pairs = parse_qsl(
            init_data,
            keep_blank_values=True,
            strict_parsing=True,
            encoding="utf-8",
            errors="strict",
            max_num_fields=100,
        )
    except ValueError as exc:
        raise ValueError("Некорректный initData") from exc

    data = dict(pairs)
    if not data or len(data) != len(pairs) or "" in data:
        raise ValueError("Пустой initData или повторяющиеся/пустые ключи")
    return data


def _check_string(data: dict[str, str], exclude: set[str]) -> bytes:
    return "\n".join(
        f"{key}={value}"
        for key, value in sorted(data.items())
        if key not in exclude
    ).encode("utf-8")


def _checked_user(data: dict[str, str], max_age: int) -> dict:
    # Вызывать только после успешной криптографической проверки.
    try:
        auth_date = int(data["auth_date"])
    except (KeyError, ValueError) as exc:
        raise ValueError("Отсутствует или некорректен auth_date") from exc

    # Допускаем рассинхронизацию часов до 30 секунд.
    age = time.time() - auth_date
    if not -30 <= age <= max_age:
        raise ValueError("initData просрочен или датирован будущим")

    try:
        user = json.loads(data["user"])
    except (KeyError, ValueError) as exc:
        raise ValueError("Отсутствует или некорректен user") from exc

    if not isinstance(user, dict) or type(user.get("id")) is not int:
        raise ValueError("Некорректный user.id")
    return user


# 1. Ваш бэкенд: токен хранится только на сервере.
def validate_for_bot(
    init_data: str, bot_token: str, *, max_age: int = 300
) -> dict:
    data = _parse(init_data)

    try:
        received_hash = bytes.fromhex(data["hash"])
    except (KeyError, ValueError) as exc:
        raise ValueError("Отсутствует или некорректен hash") from exc

    secret_key = hmac.digest(
        b"WebAppData", bot_token.encode("utf-8"), "sha256"
    )
    # Исключаем ТОЛЬКО hash. signature, если есть, участвует в HMAC.
    expected_hash = hmac.digest(
        secret_key, _check_string(data, {"hash"}), "sha256"
    )
    if not hmac.compare_digest(expected_hash, received_hash):
        raise ValueError("Неверный hash")

    return _checked_user(data, max_age)


# 2. Сервис партнёра: только ожидаемый bot_id и публичный ключ Telegram.
def validate_for_partner(
    init_data: str,
    bot_id: int,
    *,
    test: bool = False,
    max_age: int = 300,
) -> dict:
    data = _parse(init_data)

    try:
        encoded = data["signature"]
        signature = base64.b64decode(
            encoded + "=" * (-len(encoded) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (KeyError, ValueError, binascii.Error) as exc:
        raise ValueError("Отсутствует или некорректна signature") from exc

    if len(signature) != 64:
        raise ValueError("Некорректная длина signature")

    # Здесь исключаем И hash, И signature.
    message = (
        f"{bot_id}:WebAppData\n".encode("utf-8")
        + _check_string(data, {"hash", "signature"})
    )
    key_hex = TELEGRAM_TEST_KEY if test else TELEGRAM_PROD_KEY
    public_key = Ed25519PublicKey.from_public_bytes(bytes.fromhex(key_hex))

    try:
        public_key.verify(signature, message)
    except InvalidSignature as exc:
        raise ValueError("Неверная signature") from exc

    return _checked_user(data, max_age)
```

Передавайте исходную строку `Telegram.WebApp.initData`, без предварительного декодирования или пересериализации `user`. Обе функции возвращают проверенный `user`; ошибки проверки вызывают `ValueError`, который обработчик может преобразовать в HTTP 401.

`bot_id` и `test` у партнёра берутся из доверенной конфигурации. `max_age=300` — выбранный здесь срок в пять минут, его можно изменить. Проверка срока ограничивает повторное использование данных; для одноразовых операций дополнительно нужна защита от повторов.

Алгоритмы и ключи: [проверка HMAC](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app), [проверка для партнёра](https://core.telegram.org/bots/webapps#validating-data-for-third-party-use).
